import test from 'node:test';
import assert from 'node:assert/strict';
import fixtures from './model-timing-fixtures.json';
import { nextDown, sampleTiming, selectedMoveInputs, timingFeatures } from './model-timing';

// Generic constructed positions, generated by the source project's feature_vector
// and selected_move_inputs, not private training examples.
test('50 timing features and move attributes match native Python across colors, castling, EP and promotions', () => {
  const logits = Float32Array.from({ length: 4352 }, (_, index) => index % 17 / 10);
  for (const { row, move, features, indices, attributes } of fixtures) {
    const actual = timingFeatures({
      fen: row.fen, historyFens: [row.fen], initialSeconds: row.initial_seconds,
      incrementSeconds: row.increment_seconds, remainingSeconds: row.remaining_seconds,
      opponentRemainingSeconds: row.opponent_remaining_seconds, ownTimeHistory: row.own_time_history,
      opponentTimeHistory: row.opponent_time_history, previousMoveWasCapture: row.previous_move_was_capture,
      eloSelf: 491, eloOpponent: 529,
    });
    assert.equal(actual.length, 50);
    features.forEach((value, index) => assert.ok(Math.abs(actual[index] - value) < 1e-6, `${move} feature ${index}`));
    const selected = selectedMoveInputs(row.fen, move, logits);
    assert.deepEqual(Array.from(selected.indices, Number), indices);
    attributes.forEach((value, index) => assert.ok(Math.abs(selected.attributes[index] - value) < 2e-6, `${move} attribute ${index}`));
  }
});

test('timing samples continuously within a bin instead of choosing centers', () => {
  const logits = new Float32Array(30).fill(-10000);
  logits[10] = 0;
  const lower = 10 ** 0 - 0.1;
  const upper = 10 ** 0.1 - 0.1;
  const sequence = [0.5, 0.25];
  const sample = sampleTiming(logits, 600, () => sequence.shift()!);
  assert.ok(Math.abs(sample - (Math.exp(Math.log(lower + 0.1) * 0.75 + Math.log(upper + 0.1) * 0.25) - 0.1)) < 1e-12);
});

test('clock truncation preserves fractional bin mass and excludes exhausted budget', () => {
  const logits = new Float32Array(30).fill(-10000);
  logits[0] = 0;
  logits[1] = 0;
  const edge = 10 ** -0.9 - 0.1;
  const clock = 10 ** -0.85 - 0.1;
  // Full first bin and half second bin -> first bin has 2/3 of retained mass.
  const first = [0.66, 0.5];
  const second = [0.67, 0.5];
  assert.ok(sampleTiming(logits, clock, () => first.shift()!) < edge);
  assert.ok(sampleTiming(logits, clock, () => second.shift()!) > edge);
  for (const clock of [1e-10, 0.01, 0.5, 1, 50, 600]) {
    const sample = sampleTiming(new Float32Array(30), clock, () => 0.9999999);
    assert.ok(sample >= 0 && sample < clock);
  }
  assert.throws(() => sampleTiming(logits, 0));
  assert.throws(() => sampleTiming(new Float32Array(30).fill(NaN), 10));
  assert.ok(nextDown(600) < 600);
});
